INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20701, 'វត្ថុមួយផ្លាស់ទីដោយចម្ងាយ \(S(t)=5t^2+2t\) (m) ។ តើល្បឿនត្រង់ \(t=3\ \text{s}\) ស្មើប៉ុន្មាន ?', NULL, '["\\(47\\ \\text{m/s}\\)", "\\(32\\ \\text{m/s}\\)", "\\(15\\ \\text{m/s}\\)", "\\(30\\ \\text{m/s}\\)"]', 1, NULL, 1, 'mcq', '\(V(t)=S''(t)=10t+2\) ដូច្នេះ \(V(3)=32\) m/s។', 'ចលនា ល្បឿន និងសំទុះ', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20702, 'ចតុកោណកែងមួយមានបរិមាត្រ \(40\ \text{m}\) ។ ផ្ទៃក្រឡា \(A(x)=x(20-x)\) ដែល \(x\) ជាទទឹង ។ តើ \(x\) ស្មើប៉ុន្មាន ដើម្បីឱ្យផ្ទៃក្រឡាធំបំផុត ?', NULL, '["\\(x=20\\ \\text{m}\\)", "\\(x=10\\ \\text{m}\\)", "\\(x=5\\ \\text{m}\\)", "\\(x=40\\ \\text{m}\\)"]', 1, NULL, 1, 'mcq', '\(A''(x)=20-2x=0\) ដូច្នេះ \(x=10\) (ការ៉េ)។', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20703, 'កាំរង្វង់មួយកើនដោយអត្រា \(2\ \text{cm/s}\) ។ តើផ្ទៃក្រឡារង្វង់កើនដោយអត្រាប៉ុន្មាន ត្រង់ \(r=5\ \text{cm}\) ?', NULL, '["\\(25\\pi\\ \\text{cm}^2/\\text{s}\\)", "\\(5\\pi\\ \\text{cm}^2/\\text{s}\\)", "\\(10\\pi\\ \\text{cm}^2/\\text{s}\\)", "\\(20\\pi\\ \\text{cm}^2/\\text{s}\\)"]', 3, NULL, 1, 'mcq', '\(\dfrac{dA}{dt}=2\pi r\dfrac{dr}{dt}=2\pi\cdot5\cdot2=20\pi\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20704, 'ចម្ងាយ \(S(t)=t^3-3t\) (m) ។ តើសំទុះត្រង់ \(t=2\ \text{s}\) ស្មើប៉ុន្មាន ?', NULL, '["\\(6\\ \\text{m/s}^2\\)", "\\(9\\ \\text{m/s}^2\\)", "\\(3\\ \\text{m/s}^2\\)", "\\(12\\ \\text{m/s}^2\\)"]', 3, NULL, 1, 'mcq', '\(V=S''=3t^2-3\) ; \(a=V''=6t\) ដូច្នេះ \(a(2)=12\)។', 'ចលនា ល្បឿន និងសំទុះ', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20705, 'អនុគមន៍ \(A(x)=60x-x^2\) មានតម្លៃអតិបរមាត្រង់ \(x\) ស្មើប៉ុន្មាន ?', NULL, '["\\(x=15\\)", "\\(x=60\\)", "\\(x=30\\)", "\\(x=0\\)"]', 2, NULL, 1, 'mcq', '\(A''(x)=60-2x=0\) ដូច្នេះ \(x=30\)។', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20706, 'ស៊ីឡាំងមួយមានកាំបាត \(5\ \text{cm}\) ថេរ ហើយកម្ពស់ \(h\) កើនដោយអត្រា \(3\ \text{cm/s}\) ។ តើមាឌកើនដោយអត្រាប៉ុន្មាន ?', NULL, '["\\(25\\pi\\ \\text{cm}^3/\\text{s}\\)", "\\(75\\pi\\ \\text{cm}^3/\\text{s}\\)", "\\(30\\pi\\ \\text{cm}^3/\\text{s}\\)", "\\(15\\pi\\ \\text{cm}^3/\\text{s}\\)"]', 1, NULL, 1, 'mcq', '\(V=25\pi h\) ដូច្នេះ \(\dfrac{dV}{dt}=25\pi\cdot3=75\pi\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20707, 'ល្បឿននៃចលនាមួយនៅខណៈ \(t\) ជាអ្វី ដោយប្រៀបធៀបនឹងចម្ងាយ \(S(t)\) ?', NULL, '["\\(V(t)=S''(t)=\\dfrac{dS}{dt}\\)", "\\(V(t)=S''''(t)\\)", "\\(V(t)=S(t)\\cdot t\\)", "\\(V(t)=\\displaystyle\\int S\\,dt\\)"]', 0, NULL, 1, 'mcq', 'ល្បឿនគឺដេរីវេទី ១ នៃចម្ងាយ ; សំទុះគឺដេរីវេទី ២។', 'ចលនា ល្បឿន និងសំទុះ', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20708, 'អនុគមន៍ \(f(x)=x^2-6x+5\) មានតម្លៃអប្បបរមាស្មើប៉ុន្មាន ?', NULL, '["\\(-4\\)", "\\(5\\)", "\\(3\\)", "\\(-6\\)"]', 0, NULL, 1, 'mcq', '\(f''(x)=2x-6=0\) ដូច្នេះ \(x=3\) ហើយ \(f(3)=9-18+5=-4\)។', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20709, 'ទំនាក់ទំនងរវាងសំទុះ \(a(t)\) និងល្បឿន \(V(t)\) គឺ ៖', NULL, '["\\(a(t)=\\dfrac{V(t)}{t}\\)", "\\(V(t)=a''(t)\\)", "\\(a(t)=V''(t)=\\dfrac{dV}{dt}\\)", "\\(a(t)=V(t)^2\\)"]', 2, NULL, 1, 'mcq', 'សំទុះជាអត្រាបម្រែបម្រួលនៃល្បឿន \(a=\dfrac{dV}{dt}\)។', 'ចលនា ល្បឿន និងសំទុះ', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20710, 'ល្បឿន \(V(t)=4t+1\) (m/s) ។ តើសំទុះស្មើប៉ុន្មាន ?', NULL, '["\\(4\\ \\text{m/s}^2\\)", "\\(5\\ \\text{m/s}^2\\)", "\\(4t\\ \\text{m/s}^2\\)", "\\(1\\ \\text{m/s}^2\\)"]', 0, NULL, 1, 'mcq', '\(a(t)=V''(t)=4\) (ថេរ)។', 'ចលនា ល្បឿន និងសំទុះ', 'easy', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20711, 'ប្រអប់បើកធ្វើពីក្រដាសការ៉េ \(10\times10\) ដោយកាត់ការ៉េជ្រុង \(x\) ត្រង់ជ្រុងទាំងបួន ។ មាឌ \(V(x)=x(10-2x)^2\) ។ តើ \(x\) ស្មើប៉ុន្មាន ដើម្បីឱ្យមាឌអតិបរមា ?', NULL, '["\\(x=5\\)", "\\(x=\\dfrac{10}3\\)", "\\(x=1\\)", "\\(x=\\dfrac53\\)"]', 3, NULL, 2, 'mcq', '\(V''(x)=(10-2x)(10-6x)=0\) ដូច្នេះ \(x=5\) (មិនយក) ឬ \(x=\dfrac53\)។', 'បញ្ហាធរណីមាត្រ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20712, 'ចំនួនពីរមានផលបូក \(20\) ។ តើផលគុណអតិបរមាស្មើប៉ុន្មាន ?', NULL, '["\\(100\\)", "\\(96\\)", "\\(200\\)", "\\(80\\)"]', 0, NULL, 2, 'mcq', 'តាង \(P(x)=x(20-x)\) ; \(P''=20-2x=0\) ឱ្យ \(x=10\) ហើយ \(P=100\)។', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20713, 'ប្រាក់ចំណេញ \(P(x)=-x^2+80x-300\) (ពាន់រៀល) ដែល \(x\) ជាចំនួនឯកតាផលិត ។ តើចំណេញអតិបរមាស្មើប៉ុន្មាន ?', NULL, '["\\(40\\)", "\\(1\\,600\\)", "\\(1\\,000\\)", "\\(1\\,300\\)"]', 3, NULL, 2, 'mcq', '\(P''=-2x+80=0\) ឱ្យ \(x=40\) ហើយ \(P(40)=-1\,600+3\,200-300=1\,300\) ពាន់រៀល។', 'ចំណេញ ចំណាយ និងតម្លៃលក់', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20714, 'ទឹកចូលស៊ីឡាំងកាំបាត \(10\ \text{cm}\) ដោយអត្រាមាឌ \(200\ \text{cm}^3/\text{s}\) ។ តើកម្រិតទឹកកើនដោយអត្រាប៉ុន្មាន ?', NULL, '["\\(2\\pi\\ \\text{cm/s}\\)", "\\(\\dfrac{20}{\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac2\\pi\\ \\text{cm/s}\\)", "\\(2\\ \\text{cm/s}\\)"]', 2, NULL, 2, 'mcq', '\(V=100\pi h\) ដូច្នេះ \(\dfrac{dh}{dt}=\dfrac{200}{100\pi}=\dfrac2\pi\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20715, 'ទីតាំង \(S(t)=t^3-9t^2+24t\) (m) ។ ល្បឿនសូន្យត្រង់ពេលណា ?', NULL, '["\\(t=2\\) និង \\(t=4\\)", "\\(t=1\\) និង \\(t=3\\)", "\\(t=3\\) តែមួយ", "\\(t=0\\) និង \\(t=6\\)"]', 0, NULL, 2, 'mcq', '\(V=3t^2-18t+24=3(t-2)(t-4)\) ។', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20716, 'ចតុកោណកែងមួយមានផ្ទៃក្រឡា \(100\ \text{m}^2\) ។ បរិមាត្រ \(p(x)=2x+\dfrac{200}{x}\) ។ តើ \(x\) ស្មើប៉ុន្មាន ដើម្បីឱ្យបរិមាត្រតូចបំផុត ?', NULL, '["\\(x=5\\ \\text{m}\\)", "\\(x=10\\ \\text{m}\\)", "\\(x=\\sqrt{50}\\ \\text{m}\\)", "\\(x=20\\ \\text{m}\\)"]', 1, NULL, 2, 'mcq', '\(p''(x)=2-\dfrac{200}{x^2}=0\) ដូច្នេះ \(x^2=100\) គឺ \(x=10\) (ការ៉េ)។', 'បញ្ហាធរណីមាត្រ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20717, 'ចំណូលសរុប \(R(p)=p(100-2p)\) ដែល \(p\) ជាតម្លៃលក់ ។ តើ \(p\) ស្មើប៉ុន្មាន ដើម្បីឱ្យចំណូលអតិបរមា ?', NULL, '["\\(p=50\\)", "\\(p=25\\)", "\\(p=100\\)", "\\(p=12{,}5\\)"]', 1, NULL, 2, 'mcq', '\(R''=100-4p=0\) ដូច្នេះ \(p=25\)។', 'ចំណេញ ចំណាយ និងតម្លៃលក់', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20718, 'កោនមាឌ \(V=\dfrac{\pi h^3}{75}\) ត្រូវបានបំពេញដោយអត្រា \(3\ \text{cm}^3/\text{s}\) ។ តើ \(\dfrac{dh}{dt}\) ស្មើប៉ុន្មាន ត្រង់ \(h=15\ \text{cm}\) ?', NULL, '["\\(\\dfrac1{3\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac{1}{\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac{1}{9\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac{3}{25\\pi}\\ \\text{cm/s}\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{dV}{dt}=\dfrac{\pi h^2}{25}\dfrac{dh}{dt}\) ដូច្នេះ \(3=9\pi\dfrac{dh}{dt}\) គឺ \(\dfrac{dh}{dt}=\dfrac1{3\pi}\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20719, 'ល្បឿន \(V(t)=t^2-6t+5\) ។ ល្បឿនអប្បបរមាត្រង់ពេលណា ?', NULL, '["\\(t=5\\)", "\\(t=1\\)", "\\(t=3\\)", "\\(t=6\\)"]', 2, NULL, 2, 'mcq', '\(a=V''=2t-6=0\) ដូច្នេះ \(t=3\) (ហើយ \(V(3)=-4\))។', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20720, 'ផ្ទៃក្រឡារង្វង់កើនដោយអត្រា \(4\pi\ \text{cm}^2/\text{s}\) ។ តើកាំកើនដោយអត្រាប៉ុន្មាន ត្រង់ \(r=2\ \text{cm}\) ?', NULL, '["\\(4\\ \\text{cm/s}\\)", "\\(2\\ \\text{cm/s}\\)", "\\(\\dfrac12\\ \\text{cm/s}\\)", "\\(1\\ \\text{cm/s}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{dA}{dt}=2\pi r\dfrac{dr}{dt}\) ដូច្នេះ \(4\pi=4\pi\dfrac{dr}{dt}\) គឺ \(\dfrac{dr}{dt}=1\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20721, 'ល្បឿន \(V(t)=\dfrac{20t}{t+4}\) (m/s) ។ សំទុះត្រង់ \(t=1\) ស្មើប៉ុន្មាន ?', NULL, '["\\(5\\ \\text{m/s}^2\\)", "\\(2{,}4\\ \\text{m/s}^2\\)", "\\(3{,}2\\ \\text{m/s}^2\\)", "\\(4\\ \\text{m/s}^2\\)"]', 2, NULL, 2, 'mcq', '\(a=V''=\dfrac{80}{(t+4)^2}\) ដូច្នេះ \(a(1)=\dfrac{80}{25}=3{,}2\)។', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20722, 'វត្ថុធ្លាក់ដោយសេរី \(S(t)=4{,}9t^2\) (m) ។ ល្បឿនត្រង់ \(t=2{,}5\ \text{s}\) ស្មើប៉ុន្មាន ?', NULL, '["\\(12{,}25\\ \\text{m/s}\\)", "\\(30{,}6\\ \\text{m/s}\\)", "\\(24{,}5\\ \\text{m/s}\\)", "\\(9{,}8\\ \\text{m/s}\\)"]', 2, NULL, 2, 'mcq', '\(V=9{,}8t\) ដូច្នេះ \(V(2{,}5)=24{,}5\)។', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20723, 'ទីតាំង \(S(t)=t^2-4t\) (m) ។ ត្រង់ \(t=1\) តើវត្ថុចលនាតាមទិសណា ?', NULL, '["ឈប់ ព្រោះ \\(V(1)=0\\)", "ថយក្រោយ (ទិសអវិជ្ជមាន) ព្រោះ \\(V(1)=-2<0\\)", "ទៅមុខ ព្រោះ \\(V(1)=2>0\\)", "ទៅមុខ ព្រោះ \\(S(1)=-3<0\\)"]', 1, NULL, 2, 'mcq', '\(V=S''=2t-4\) ដូច្នេះ \(V(1)=-2<0\) គឺវត្ថុថយក្រោយ។', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20724, 'ទីតាំង \(S(t)=t^2\) (m) ។ តើល្បឿនមធ្យមរវាង \(t=1\) និង \(t=3\) ស្មើប៉ុន្មាន ?', NULL, '["\\(6\\ \\text{m/s}\\)", "\\(9\\ \\text{m/s}\\)", "\\(8\\ \\text{m/s}\\)", "\\(4\\ \\text{m/s}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{S(3)-S(1)}{3-1}=\dfrac{9-1}{2}=4\) (ខុសពីល្បឿនខណៈ \(V(3)=6\) ដែលជាដេរីវេ)។', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20725, 'ប្រអប់បើកធ្វើពីក្រដាសការ៉េ \(12\times12\) ដោយកាត់ការ៉េជ្រុង \(x\) ត្រង់ជ្រុងទាំងបួន ។ តើមាឌអតិបរមាស្មើប៉ុន្មាន ?', NULL, '["\\(96\\)", "\\(144\\)", "\\(108\\)", "\\(128\\)"]', 3, NULL, 3, 'mcq', '\(V=x(12-2x)^2\) ; \(V''=(12-2x)(12-6x)=0\) ឱ្យ \(x=2\) ហើយ \(V(2)=2\cdot64=128\)។', 'បញ្ហាធរណីមាត្រ', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20726, 'កោនមាឌ \(V=\dfrac{\pi h^3}{75}\) ត្រូវបំពេញដោយអត្រា \(8\ \text{cm}^3/\text{s}\) ។ តើ \(\dfrac{dh}{dt}\) ស្មើប៉ុន្មាន ត្រង់ \(h=10\ \text{cm}\) ?', NULL, '["\\(\\dfrac{25}{\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac2\\pi\\ \\text{cm/s}\\)", "\\(\\dfrac{1}{\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac{8}{\\pi}\\ \\text{cm/s}\\)"]', 1, NULL, 3, 'mcq', '\(\dfrac{dV}{dt}=\dfrac{\pi h^2}{25}\dfrac{dh}{dt}=4\pi\dfrac{dh}{dt}=8\) ដូច្នេះ \(\dfrac{dh}{dt}=\dfrac2\pi\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20727, 'ទីតាំង \(S(t)=t^3-6t^2+9t\) (m) ពេល \(0\le t\le4\) ។ តើចម្ងាយសរុបដែលវត្ថុធ្វើដំណើរស្មើប៉ុន្មាន ?', NULL, '["\\(8\\ \\text{m}\\)", "\\(4\\ \\text{m}\\)", "\\(12\\ \\text{m}\\)", "\\(0\\ \\text{m}\\)"]', 2, NULL, 3, 'mcq', '\(V=3(t-1)(t-3)\) ៖ វត្ថុទៅ \(S(1)=4\), ថយ \(S(3)=0\), ទៅ \(S(4)=4\) ។ ចម្ងាយសរុប \(4+4+4=12\) (មិនមែនបម្រែបម្រួលទីតាំង \(S(4)-S(0)=4\))។', 'ចលនា ល្បឿន និងសំទុះ', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20728, 'សិស្សម្នាក់រកឃើញ \(A''(x)=0\) ត្រង់ \(x=100\) ហើយសន្និដ្ឋានថា \(A\) មានអតិបរមាត្រង់នោះ ។ តើហេតុផលណាបញ្ជាក់បានត្រឹមត្រូវ ?', NULL, '["\\(A(100)>0\\) ដូច្នេះអតិបរមា", "\\(A''\\) មានត្រង់ \\(x=100\\) ដូច្នេះអតិបរមា", "\\(A''\\) ប្ដូរសញ្ញាពី \\(+\\) ទៅ \\(-\\) ត្រង់ \\(x=100\\) (ឬ \\(A''''(100)<0\\))", "\\(A''(100)=0\\) តែមួយ ក៏គ្រប់គ្រាន់"]', 2, NULL, 3, 'mcq', 'ឫសនៃ \(A''=0\) អាចជាអតិបរមា អប្បបរមា ឬចំណុចរាបស្មើ (ឧ. \(x^3\) ត្រង់ \(0\)) ។ ត្រូវមើលសញ្ញា \(A''\) ឬ \(A''''\)។', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20729, 'ស៊ីឡាំងមួយមានមាឌថេរ \(V\) ។ តើផលធៀបកម្ពស់ទៅកាំ \(\dfrac hr\) ស្មើប៉ុន្មាន ដើម្បីឱ្យផ្ទៃក្រឡាសរុបតូចបំផុត ?', NULL, '["\\(4\\)", "\\(2\\)", "\\(1\\)", "\\(\\dfrac12\\)"]', 1, NULL, 3, 'mcq', '\(S=2\pi r^2+\dfrac{2V}{r}\) ; \(S''=4\pi r-\dfrac{2V}{r^2}=0\) ដូច្នេះ \(V=2\pi r^3\) គឺ \(h=\dfrac V{\pi r^2}=2r\)។', 'បញ្ហាធរណីមាត្រ', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20730, 'ជណ្ដើរប្រវែង \(10\ \text{m}\) ទល់ជញ្ជាំង ។ ជើងជណ្ដើរដើរឆ្ងាយពីជញ្ជាំងដោយអត្រា \(1\ \text{m/s}\) ។ តើកំពូលជណ្ដើរធ្លាក់ចុះដោយអត្រាប៉ុន្មាន កាលណាជើងនៅចម្ងាយ \(6\ \text{m}\) ?', NULL, '["\\(0{,}75\\ \\text{m/s}\\)", "\\(1{,}33\\ \\text{m/s}\\)", "\\(0{,}6\\ \\text{m/s}\\)", "\\(1\\ \\text{m/s}\\)"]', 0, NULL, 3, 'mcq', '\(x^2+y^2=100\) ដូច្នេះ \(2xx''+2yy''=0\) គឺ \(y''=-\dfrac xyx''=-\dfrac68\cdot1=-0{,}75\) (ពេល \(x=6,\ y=8\))។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20731, 'ចតុកោណកែងចារឹកក្នុងរង្វង់កាំ \(5\) ។ តើផ្ទៃក្រឡាអតិបរមាស្មើប៉ុន្មាន ?', NULL, '["\\(50\\)", "\\(48\\)", "\\(25\\pi\\)", "\\(40\\)"]', 0, NULL, 3, 'mcq', 'ចំពោះជ្រុងពាក់កណ្ដាល \(x\) ៖ \(A=4x\sqrt{25-x^2}\) ; អតិបរមាកាលណា \(x=\dfrac5{\sqrt2}\) (ការ៉េ) ហើយ \(A=50\)។', 'បញ្ហាធរណីមាត្រ', 'hard', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
