INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20732, 'កសិករម្នាក់មានរបង \(120\ \text{m}\) ដើម្បីព័ទ្ធចម្ការមួយខាងទន្លេ (មិនត្រូវការរបងខាងទន្លេ) ដូចក្នុងរូប ។ ទទឹង \(x\) ដែលផ្ដល់ផ្ទៃក្រឡាធំបំផុតគឺ ?', 'g12sc-bec9c3a9ad.svg', '["\\(x=20\\ \\text{m}\\)", "\\(x=40\\ \\text{m}\\)", "\\(x=30\\ \\text{m}\\)", "\\(x=60\\ \\text{m}\\)"]', 2, NULL, 3, 'mcq', '\(y=120-2x\) ; \(A=x(120-2x)\) ; \(A''=120-4x=0\) ដូច្នេះ \(x=30\) (\(A=1\,800\ \text{m}^2\))។', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'pisa', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
