INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20733, 'ហាងមួយលក់ទំនិញមួយ ដែលតម្លៃចំណាយ \(20\) ដុល្លារ/ឯកតា ហើយបរិមាណលក់ \(q=1\,000-4p\) ដែល \(p\) ជាតម្លៃលក់ ។ ចំណេញ \(P(p)=(p-20)(1\,000-4p)\) ដូចក្នុងរូប ។ តើតម្លៃលក់ \(p\) ណាផ្ដល់ចំណេញអតិបរមា ?', 'g12sc-378e815a9f.svg', '["\\(p=135\\)", "\\(p=20\\)", "\\(p=250\\)", "\\(p=100\\)"]', 0, NULL, 3, 'mcq', '\(P''=(1\,000-4p)-4(p-20)=1\,080-8p=0\) ដូច្នេះ \(p=135\) ដុល្លារ។', 'ចំណេញ ចំណាយ និងតម្លៃលក់', 'pisa', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
