INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20734, 'រថយន្តមួយមានល្បឿន \(V(t)=\dfrac{60t}{t+6}\) (m/s) ដូចក្នុងរូប ។ តើសំទុះត្រង់ \(t=6\ \text{s}\) ស្មើប៉ុន្មាន ?', 'g12sc-f56e0f002f.svg', '["\\(10\\ \\text{m/s}^2\\)", "\\(2{,}5\\ \\text{m/s}^2\\)", "\\(30\\ \\text{m/s}^2\\)", "\\(5\\ \\text{m/s}^2\\)"]', 1, NULL, 3, 'mcq', '\(a=V''=\dfrac{360}{(t+6)^2}\) ដូច្នេះ \(a(6)=\dfrac{360}{144}=2{,}5\)។', 'ចលនា ល្បឿន និងសំទុះ', 'pisa', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-426f93e4ad.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20735, 'ធុងស៊ីឡាំងកាំបាត \(20\ \text{cm}\) ទទួលទឹក \(1{,}2\ \text{L/s}\) ហើយបង្ហូរចេញ \(0{,}4\ \text{L/s}\) ដូចក្នុងរូប ។ តើកម្រិតទឹកកើនដោយអត្រាប៉ុន្មាន ? ( \(1\ \text{L}=1\,000\ \text{cm}^3\) )', 'g12sc-426f93e4ad.svg', '["\\(\\dfrac{1}{\\pi}\\ \\text{cm/s}\\)", "\\(\\dfrac{4}{\\pi}\\ \\text{cm/s}\\)", "\\(2\\ \\text{cm/s}\\)", "\\(\\dfrac2\\pi\\ \\text{cm/s}\\approx0{,}64\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{dV}{dt}=1\,200-400=800\ \text{cm}^3/\text{s}\) ; \(V=400\pi h\) ដូច្នេះ \(\dfrac{dh}{dt}=\dfrac{800}{400\pi}=\dfrac2\pi\)។', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'pisa', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-3795c06c17.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20736, 'គេបោះបាល់ឡើងលើ កម្ពស់ \(h(t)=20t-5t^2\) (m) ដូចក្នុងរូប ។ តើកម្ពស់អតិបរមាស្មើប៉ុន្មាន ?', 'g12sc-3795c06c17.svg', '["\\(10\\ \\text{m}\\)", "\\(40\\ \\text{m}\\)", "\\(15\\ \\text{m}\\)", "\\(20\\ \\text{m}\\)"]', 3, NULL, 3, 'mcq', '\(h''=20-10t=0\) ដូច្នេះ \(t=2\) ហើយ \(h(2)=40-20=20\) m។', 'ចលនា ល្បឿន និងសំទុះ', 'pisa', 1, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20737, 'ទីតាំងនៃវត្ថុមួយ \(S(t)=3t^2+2t\) (m) ។ ក. រកល្បឿន \(V(t)\) ។ ខ. រកសំទុះ \(a(t)\) ។ គ. គណនាល្បឿននិងសំទុះត្រង់ \(t=2\ \text{s}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ល្បឿនជាដេរីវេនៃទីតាំង ៖ \(V(t)=S''(t)=6t+2\) (1 ពិន្ទុ)
ខ. សំទុះជាដេរីវេនៃល្បឿន ៖ \(a(t)=V''(t)=6\) (1 ពិន្ទុ)
គ. ជំនួស \(t=2\) ក្នុង \(V\) ៖ \(V(2)=6\cdot2+2=14\ \text{m/s}\) (1 ពិន្ទុ)
សំទុះថេរ ៖ \(a(2)=6\ \text{m/s}^2\) (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ ល្បឿនកើនឡើងដោយសំទុះថេរ \(6\ \text{m/s}^2\) (ចលនាបង្កើនល្បឿនស្មើ)។ (1 ពិន្ទុ)', 'ចលនា ល្បឿន និងសំទុះ', 'easy', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20738, 'ចម្ការរាងចតុកោណកែងមួយមានបរិមាត្រ \(60\ \text{m}\) ។ ក. សរសេរផ្ទៃក្រឡាជាអនុគមន៍នៃទទឹង \(x\) ។ ខ. រក \(x\) ដែលផ្ទៃក្រឡាធំបំផុត ហើយបញ្ជាក់ថាជាអតិបរមា ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បរិមាត្រ \(2x+2y=60\) ដូច្នេះ \(y=30-x\) (1 ពិន្ទុ)
ផ្ទៃក្រឡា \(A(x)=xy=x(30-x)=30x-x^2\) ដែល \(0<x<30\) (1 ពិន្ទុ)
ខ. \(A''(x)=30-2x\) ; \(A''(x)=0\) ឱ្យ \(x=15\) (1 ពិន្ទុ)
បញ្ជាក់ ៖ \(A''''(x)=-2<0\) ដូច្នេះ \(x=15\) ជាអតិបរមា (1 ពិន្ទុ)
\(y=30-15=15\) ដូច្នេះចម្ការជាការ៉េ ហើយ \(A_{\max}=15\times15=225\ \text{m}^2\)។ (1 ពិន្ទុ)', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'medium', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20739, 'ល្បឿនរថយន្តមួយ \(V(t)=\dfrac{18t}{t+3}\) (m/s) ។ ក. រកសំទុះ \(a(t)\) ។ ខ. គណនា \(a(0),\ a(3),\ a(9)\) ។ គ. បកស្រាយថាតើល្បឿនកើនឬចុះ និងខិតទៅរកតម្លៃណា ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(a(t)=V''(t)=\dfrac{18(t+3)-18t}{(t+3)^2}=\dfrac{54}{(t+3)^2}\) (1 ពិន្ទុ)
ខ. \(a(0)=\dfrac{54}{9}=6\ \text{m/s}^2\) (1 ពិន្ទុ)
\(a(3)=\dfrac{54}{36}=1{,}5\ \text{m/s}^2\) ហើយ \(a(9)=\dfrac{54}{144}=0{,}375\ \text{m/s}^2\) (1 ពិន្ទុ)
គ. \(a(t)>0\) ជានិច្ច ដូច្នេះល្បឿនកើនឡើងជានិច្ច ប៉ុន្តែសំទុះថយចុះ (1 ពិន្ទុ)
ល្បឿនខិតទៅ \(\displaystyle\lim_{t\to+\infty}\dfrac{18t}{t+3}=18\ \text{m/s}\) ដែលជាល្បឿនកំណត់ (សំទុះ \(\to0\))។ (1 ពិន្ទុ)', 'ចលនា ល្បឿន និងសំទុះ', 'medium', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20740, 'គេធ្វើប្រអប់បើកពីក្រដាសកាតុង \(20\ \text{cm}\times12\ \text{cm}\) ដោយកាត់ការ៉េជ្រុង \(x\) ត្រង់ម៉ុំទាំងបួន ។ ក. សរសេរមាឌ \(V(x)\) ហើយកំណត់ដែន ។ ខ. រក \(x\) ដែលមាឌអតិបរមា ហើយគណនាមាឌនោះ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ទទឹង \(12-2x>0\) ដូច្នេះ \(0<x<6\) ; \(V(x)=x(20-2x)(12-2x)=4x^3-64x^2+240x\) (1 ពិន្ទុ)
ខ. \(V''(x)=12x^2-128x+240=4(3x^2-32x+60)\) (1 ពិន្ទុ)
ដោះស្រាយ \(3x^2-32x+60=0\) ៖ \(x=\dfrac{32\pm\sqrt{304}}6\) គឺ \(x\approx2{,}43\) ឬ \(x\approx8{,}24\) (មិនក្នុងដែន) (1 ពិន្ទុ)
សញ្ញា \(V''\) ប្ដូរពី \(+\) ទៅ \(-\) ត្រង់ \(x\approx2{,}43\) ដូច្នេះអតិបរមា (1 ពិន្ទុ)
\(V(2{,}43)\approx2{,}43\times15{,}15\times7{,}15\approx263\ \text{cm}^3\)។ (1 ពិន្ទុ)', 'បញ្ហាធរណីមាត្រ', 'medium', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20741, 'គេបូមខ្យល់ចូលក្នុងប៉េងប៉ោងរាងស្វ៊ែរដោយអត្រា \(100\ \text{cm}^3/\text{s}\) ។ ក. សរសេរទំនាក់ទំនងរវាង \(\dfrac{dV}{dt}\) និង \(\dfrac{dr}{dt}\) ។ ខ. រក \(\dfrac{dr}{dt}\) ពេល \(r=10\ \text{cm}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មាឌស្វ៊ែរ \(V=\dfrac43\pi r^3\) (1 ពិន្ទុ)
ដេរីវេទាក់ទង \(t\) (អនុគមន៍បណ្ដាក់) ៖ \(\dfrac{dV}{dt}=4\pi r^2\dfrac{dr}{dt}\) (1 ពិន្ទុ)
ខ. ជំនួស \(\dfrac{dV}{dt}=100\) និង \(r=10\) ៖ \(100=4\pi(100)\dfrac{dr}{dt}\) (1 ពិន្ទុ)
ដូច្នេះ \(\dfrac{dr}{dt}=\dfrac{100}{400\pi}=\dfrac1{4\pi}\approx0{,}0\,796\ \text{cm/s}\) (1 ពិន្ទុ)
កាំកើនយឺត ព្រោះផ្ទៃស្វ៊ែរធំ ដូច្នេះអត្រាកើនកាំតូចទោះបីមាឌកើនអត្រាថេរ។ (1 ពិន្ទុ)', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'medium', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20742, 'ក្នុងចតុកោណកែងទាំងអស់ដែលមានបរិមាត្រ \(P\) ថេរ បង្ហាញថាការ៉េមានផ្ទៃក្រឡាធំបំផុត ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(x\) ជាទទឹង ហើយបណ្ដោយ \(y=\dfrac P2-x\) ដែល \(0<x<\dfrac P2\) (1 ពិន្ទុ)
ផ្ទៃក្រឡា \(A(x)=x\left(\dfrac P2-x\right)=\dfrac P2x-x^2\) (1 ពិន្ទុ)
ដេរីវេ \(A''(x)=\dfrac P2-2x=0\) ឱ្យ \(x=\dfrac P4\) (1 ពិន្ទុ)
សញ្ញា \(A''\) ប្ដូរ \(+\to-\) (ឬ \(A''''=-2<0\)) ដូច្នេះអតិបរមា (1 ពិន្ទុ)
ពេលនោះ \(y=\dfrac P2-\dfrac P4=\dfrac P4=x\) ដូច្នេះជាការ៉េ ហើយ \(A_{\max}=\dfrac{P^2}{16}\)។ (1 ពិន្ទុ)', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'hard', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20743, 'ហាងមួយទិញទំនិញតម្លៃ \(3\) ដុល្លារ/ឯកតា ហើយបរិមាណលក់ \(q(p)=600-50p\) ដែល \(p\) ជាតម្លៃលក់ ។ ក. សរសេរប្រាក់ចំណេញ \(P(p)\) ។ ខ. រកតម្លៃលក់ដែលចំណេញអតិបរមា និងចំណេញនោះ ។ គ. ពិនិត្យថាតម្លៃនេះមានន័យក្នុងបរិបទ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ចំណេញក្នុង ១ ឯកតា \(p-3\) ដូច្នេះ \(P(p)=(p-3)(600-50p)\) (1 ពិន្ទុ)
ខ. \(P''(p)=(600-50p)-50(p-3)=750-100p\) (1 ពិន្ទុ)
\(P''(p)=0\) ឱ្យ \(p=7{,}5\) ; \(P''''=-100<0\) ដូច្នេះអតិបរមា (1 ពិន្ទុ)
ចំណេញអតិបរមា \(P(7{,}5)=(4{,}5)(225)=1\,012{,}5\) ដុល្លារ (1 ពិន្ទុ)
គ. បរិមាណលក់ \(q(7{,}5)=600-375=225>0\) និង \(p>3\) ដូច្នេះមានន័យ (\(q\ge0\) ពេល \(p\le12\))។ (1 ពិន្ទុ)', 'ចំណេញ ចំណាយ និងតម្លៃលក់', 'hard', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20744, 'គេឱ្យ \(S(t)=t^3-6t^2+9t\) (m) ។ វាយតម្លៃសេចក្ដីអះអាង "ពេលល្បឿនស្មើសូន្យ វត្ថុឈប់ជាអចិន្ត្រៃយ៍" ។', NULL, '[]', 0, NULL, 5, 'writing', 'ល្បឿន \(V(t)=3t^2-12t+9=3(t-1)(t-3)\) សូន្យត្រង់ \(t=1\) និង \(t=3\) (1 ពិន្ទុ)
សំទុះ \(a(t)=6t-12\) ដូច្នេះ \(a(1)=-6\ne0\) និង \(a(3)=6\ne0\) (1 ពិន្ទុ)
ដោយសំទុះមិនសូន្យ ល្បឿនប្ដូរសញ្ញាត្រង់ \(t=1\) (ពី \(+\) ទៅ \(-\)) និង \(t=3\) (ពី \(-\) ទៅ \(+\)) (1 ពិន្ទុ)
ដូច្នេះវត្ថុឈប់តែមួយប៉ព្រិចភ្នែក ហើយប្ដូរទិស ; \(S(1)=4\) ជាចំណុចឆ្ងាយបំផុត និង \(S(3)=0\) ត្រលប់មកគល់ (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ សេចក្ដីអះអាងមិនត្រឹមត្រូវ (ឈប់ជាអចិន្ត្រៃយ៍ ទាល់តែ \(V\equiv0\) និង \(a\equiv0\))។ (1 ពិន្ទុ)', 'ចលនា ល្បឿន និងសំទុះ', 'hard', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20745, 'រចនាកំប៉ុងស៊ីឡាំងមួយមានមាឌ \(500\ \text{cm}^3\) ដោយប្រើសម្ភារៈតិចបំផុត (ផ្ទៃក្រឡាសរុបតូចបំផុត) ។ ក. សរសេរផ្ទៃក្រឡា \(S(r)\) ។ ខ. រក \(r\) និង \(h\) ដែលល្អបំផុត ។ គ. គណនា \(S_{\min}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\pi r^2h=500\) ដូច្នេះ \(h=\dfrac{500}{\pi r^2}\) ; \(S=2\pi r^2+2\pi rh=2\pi r^2+\dfrac{1\,000}{r}\) (1 ពិន្ទុ)
ខ. \(S''(r)=4\pi r-\dfrac{1\,000}{r^2}=0\) ឱ្យ \(r^3=\dfrac{250}{\pi}\) (1 ពិន្ទុ)
\(r=\sqrt[3]{250/\pi}\approx4{,}30\ \text{cm}\) ហើយ \(h=\dfrac{500}{\pi r^2}=2r\approx8{,}60\ \text{cm}\) (1 ពិន្ទុ)
ពិនិត្យអប្បបរមា ៖ \(S''''=4\pi+\dfrac{2\,000}{r^3}>0\) (1 ពិន្ទុ)
គ. \(S_{\min}=2\pi(4{,}30)^2+\dfrac{1\,000}{4{,}30}\approx116{,}2+232{,}6\approx348{,}8\ \text{cm}^2\)។ (1 ពិន្ទុ)', 'បញ្ហាធរណីមាត្រ', 'hard', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Create');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20746, 'កសិករម្នាក់មានរបង \(120\ \text{m}\) ដើម្បីព័ទ្ធចម្ការរាងចតុកោណកែងមួយខាងទន្លេ (មិនត្រូវការរបងខាងទន្លេ) ដូចក្នុងរូប ។ ក. សរសេរផ្ទៃក្រឡា \(A(x)\) ។ ខ. រកទំហំដែលផ្ទៃក្រឡាធំបំផុត ។ គ. ប្រៀបធៀបនឹងចម្ការការ៉េមានរបងដូចគ្នាបួនជ្រុង ។', 'g12sc-bec9c3a9ad.svg', '[]', 0, NULL, 5, 'writing', 'ក. របងបីខាង \(2x+y=120\) ដូច្នេះ \(y=120-2x\) ; \(A(x)=x(120-2x)=120x-2x^2\) (1 ពិន្ទុ)
ខ. \(A''(x)=120-4x=0\) ឱ្យ \(x=30\) ; \(A''''=-4<0\) អតិបរមា (1 ពិន្ទុ)
ដូច្នេះ \(x=30\ \text{m}\) ហើយ \(y=120-60=60\ \text{m}\) ; \(A_{\max}=30\times60=1\,800\ \text{m}^2\) (1 ពិន្ទុ)
គ. ការ៉េបួនជ្រុង ៖ ជ្រុង \(\dfrac{120}{4}=30\) ដូច្នេះ \(A=900\ \text{m}^2\) (1 ពិន្ទុ)
ចម្ការខាងទន្លេមានផ្ទៃក្រឡាធំជាង ព្រោះទន្លេជាជ្រុងមួយរួចហើយ (ប្រវែងបណ្ដោយ \(y=2x\))។ (1 ពិន្ទុ)', 'បញ្ហាបរមា (អតិបរមា និងអប្បបរមា)', 'pisa', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
