INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20747, 'ហាងនំលក់នំ \(200\) ដុំក្នុងមួយថ្ងៃ បើតម្លៃ \(5\) ដុល្លារ/ដុំ ។ រាល់ដងតម្លៃកើនឡើង \(0{,}5\) ដុល្លារ ការលក់ថយចុះ \(20\) ដុំ ។ ចំណាយ \(2\) ដុល្លារ/ដុំ ។ ក. បង្ហាញថាចំណេញ \(P(x)=40(x-2)(10-x)\) ដែល \(x\) ជាតម្លៃ ។ ខ. រកតម្លៃដែលចំណេញអតិបរមា ។', 'g12sc-80a98f389c.svg', '[]', 0, NULL, 5, 'writing', 'ក. ក្នុង \(x\) ដុល្លារ ការលក់ថយចុះ \(40(x-5)\) ដុំ (ព្រោះ \(0{,}5\) ឱ្យ \(20\)) (1 ពិន្ទុ)
បរិមាណលក់ \(q=200-40(x-5)=400-40x=40(10-x)\) (1 ពិន្ទុ)
ចំណេញ \(P(x)=(x-2)q=40(x-2)(10-x)\) (1 ពិន្ទុ)
ខ. \(P''(x)=40[(10-x)-(x-2)]=40(12-2x)=0\) ឱ្យ \(x=6\) (1 ពិន្ទុ)
\(P(6)=40\times4\times4=640\) ដុល្លារ (អតិបរមា ព្រោះ \(P''\) ប្ដូរ \(+\to-\)) ដូច្នេះលក់ \(6\) ដុល្លារ/ដុំ។ (1 ពិន្ទុ)', 'ចំណេញ ចំណាយ និងតម្លៃលក់', 'pisa', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20748, 'រថយន្តមួយចាប់ផ្ដើមដំណើរ ល្បឿន \(V(t)=\dfrac{60t}{t+6}\) (m/s) ដូចក្នុងរូប ។ ក. រកសំទុះ \(a(t)\) ។ ខ. រកល្បឿនកំណត់ (កាលណា \(t\to\infty\)) ។ គ. រកពេលដែលល្បឿនដល់ \(45\ \text{m/s}\) ហើយគណនាសំទុះពេលនោះ ។', 'g12sc-f56e0f002f.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(a(t)=V''(t)=\dfrac{60(t+6)-60t}{(t+6)^2}=\dfrac{360}{(t+6)^2}\) (1 ពិន្ទុ)
ខ. \(\displaystyle\lim_{t\to+\infty}\dfrac{60t}{t+6}=60\ \text{m/s}\) (អាស៊ីមតូតដេរ) (1 ពិន្ទុ)
គ. \(\dfrac{60t}{t+6}=45\) គឺ \(60t=45t+270\) (1 ពិន្ទុ)
ដូច្នេះ \(15t=270\) បាន \(t=18\ \text{s}\) (1 ពិន្ទុ)
សំទុះ \(a(18)=\dfrac{360}{24^2}=\dfrac{360}{576}=0{,}625\ \text{m/s}^2\) (សំទុះតូចក្បែរល្បឿនកំណត់)។ (1 ពិន្ទុ)', 'ចលនា ល្បឿន និងសំទុះ', 'pisa', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
