INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20749, 'គំនរខ្សាច់រាងកោនធ្លាក់ដោយអត្រា \(3\ \text{m}^3/\text{min}\) ។ កាំបាតតែងស្មើពាក់កណ្ដាលកម្ពស់ \(r=\dfrac h2\) ដូចក្នុងរូប ។ ក. បង្ហាញថា \(V=\dfrac{\pi h^3}{12}\) ។ ខ. រក \(\dfrac{dh}{dt}\) ពេល \(h=4\ \text{m}\) ។ គ. បកស្រាយថាហេតុអ្វី \(\dfrac{dh}{dt}\) ថយចុះពេលគំនរកាន់តែខ្ពស់ ។', 'g12sc-f52efa8369.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(V=\dfrac13\pi r^2h=\dfrac13\pi\left(\dfrac h2\right)^2h=\dfrac{\pi h^3}{12}\) (1 ពិន្ទុ)
ខ. ដេរីវេទាក់ទង \(t\) ៖ \(\dfrac{dV}{dt}=\dfrac{\pi h^2}{4}\dfrac{dh}{dt}\) (1 ពិន្ទុ)
ជំនួស \(\dfrac{dV}{dt}=3\) និង \(h=4\) ៖ \(3=\dfrac{\pi\cdot16}{4}\dfrac{dh}{dt}=4\pi\dfrac{dh}{dt}\) (1 ពិន្ទុ)
ដូច្នេះ \(\dfrac{dh}{dt}=\dfrac{3}{4\pi}\approx0{,}239\ \text{m/min}\) (1 ពិន្ទុ)
គ. \(\dfrac{dh}{dt}=\dfrac{4}{\pi h^2}\cdot\dfrac{dV}{dt}\) ថយចុះតាម \(\dfrac1{h^2}\) ព្រោះមុខកាត់ផ្ដេកកាន់តែធំ ដូច្នេះមាឌដូចគ្នាបង្កើនកម្ពស់តិចជាង។ (1 ពិន្ទុ)', 'អត្រាបម្រែបម្រួលដែលទាក់ទងគ្នា', 'pisa', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Analyze');
