INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 20750, 'គេបោះគ្រាប់មួយពីកម្ពស់ \(1{,}5\ \text{m}\) ឡើងលើ ហើយកម្ពស់ \(h(t)=1{,}5+20t-5t^2\) (m) ដូចក្នុងរូប ។ ក. រកពេលនិងកម្ពស់អតិបរមា ។ ខ. រកពេលដែលគ្រាប់ធ្លាក់ដល់ដី និងល្បឿនពេលប៉ះដី ។ គ. វាយតម្លៃថា "ល្បឿនពេលប៉ះដីស្មើល្បឿនបោះ \(20\ \text{m/s}\)" ។', 'g12sc-1bfe30454f.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(V(t)=h''(t)=20-10t=0\) ឱ្យ \(t=2\ \text{s}\) ; \(h(2)=1{,}5+40-20=21{,}5\ \text{m}\) (1 ពិន្ទុ)
ខ. \(h=0\) ៖ \(5t^2-20t-1{,}5=0\) ឱ្យ \(t=\dfrac{20+\sqrt{430}}{10}\approx4{,}07\ \text{s}\) (1 ពិន្ទុ)
ល្បឿនពេលប៉ះដី \(V=20-10(4{,}07)\approx-20{,}7\ \text{m/s}\) (ចុះក្រោម) (1 ពិន្ទុ)
គ. ទំហំល្បឿន \(20{,}7>20\) ដូច្នេះសេចក្ដីអះអាងមិនត្រឹមត្រូវ (1 ពិន្ទុ)
ពិនិត្យ ៖ ធ្លាក់ពីកម្ពស់អតិបរមា \(21{,}5\ \text{m}\) បាន \(V=\sqrt{2\cdot10\cdot21{,}5}=\sqrt{430}\approx20{,}7\ \text{m/s}\) ព្រោះគ្រាប់បោះពីកម្ពស់ \(1{,}5\ \text{m}\) ខ្ពស់ជាងដី ដូច្នេះល្បឿនពេលប៉ះដីធំជាងល្បឿនបោះបន្តិច។ (1 ពិន្ទុ)', 'ចលនា ល្បឿន និងសំទុះ', 'pisa', 0, '12SC', 'អនុវត្តន៍នៃដេរីវេ', 'ជំពូកទី 3 : ដេរីវេនៃអនុគមន៍', NULL, 0, 'Evaluate');
